import re, random

def cnt(n, limit, s):
    # assumes all digits of s <= limit
    suf = int(s); k = len(s)
    if n < suf: return 0
    sn = str(n); L = len(sn)
    if L < k: return 0
    # numbers with fewer digits than n
    total = 0
    if L > k:
        # length k: just s itself
        total += 1
        for length in range(k+1, L):
            m = length - k
            total += limit * (limit+1)**(m-1)
    m = L - k
    if m == 0:
        return total + (1 if sn >= s else 0)
    pre = sn[:m]
    ok = True
    for i, c in enumerate(pre):
        d = int(c)
        add = (min(d-1, limit) if i == 0 else min(d, limit+1))
        if add > 0:
            total += add * (limit+1)**(m-1-i)
        if d > limit:
            ok = False
            break
    if ok and sn[m:] >= s:
        total += 1
    return total

def f(start, finish, limit, s):
    if any(int(c) > limit for c in s):
        return 0
    return cnt(finish, limit, s) - cnt(start-1, limit, s)

def brute(start, finish, limit, s):
    suf = int(s); k = len(s)
    pat = re.compile(r'^[0-%d]*%s$' % (limit, s))
    c = 0
    for n in range(start, finish+1):
        if n % 10**k == suf and pat.match(str(n)):
            c += 1
    return c

