            m = length - k
            total += limit * (limit+1)**(m-1)
    m = L - k
    if m == 0:
        return total + (1 if sn >= s else 0)
    pre = sn[:m]
    ok = True
    for i, c in enumerate(pre):
        d = int(c)
        add = (min(d-1, limit) if i == 0 else min(d, limit+1))
        if add > 0:
